begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('91000000-0000-4000-8000-000000000001'),('91000000-0000-4000-8000-000000000002');
insert into organizations(id,name) values ('92000000-0000-4000-8000-000000000001','A'),('92000000-0000-4000-8000-000000000002','B');
insert into establishments(id,organization_id,name,timezone) values ('93000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','A','America/Sao_Paulo');
insert into memberships(organization_id,user_id,role) values ('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','owner'),('92000000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000002','owner');
insert into products(id,organization_id,establishment_id,name,unit) values ('94000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','Produto','kg');
insert into suppliers(id,organization_id,establishment_id,name) values ('95000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','Fornecedor');
insert into batch_receipts(id,organization_id,establishment_id,product_id,supplier_id,intent_id,source_code,quantity,unit,expiry_date,expiry_origin,original_expiry_date,timezone,created_by) values ('96000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000001','97000000-0000-4000-8000-000000000001','L1',1,'kg','2027-01-01','original','2027-01-01','America/Sao_Paulo','91000000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0.75,null,'98000000-0000-4000-8000-000000000001')$$,'registra consumo');
select lives_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0.75,null,'98000000-0000-4000-8000-000000000001')$$,'reenvio idempotente');
select is((select count(*) from stock_movements),1::bigint,'um evento');
select is((select created_by from stock_movements),'91000000-0000-4000-8000-000000000001'::uuid,'autor da sessão');
select throws_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0.75,null,'98000000-0000-4000-8000-000000000002')$$,'22023',null,'excesso recusado');
select throws_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0,null,'98000000-0000-4000-8000-000000000002')$$,'22023',null,'zero recusado');
select throws_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption','NaN'::numeric,null,'98000000-0000-4000-8000-000000000002')$$,'22023',null,'NaN recusado');
select throws_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0.0001,null,'98000000-0000-4000-8000-000000000002')$$,'22023',null,'precisão excessiva recusada');
select throws_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','discard',0.25,null,'98000000-0000-4000-8000-000000000002')$$,'22023',null,'descarte exige motivo');
select lives_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','discard',0.25,'dano','98000000-0000-4000-8000-000000000002')$$,'descarte encerra saldo');
select lives_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0.75,null,'98000000-0000-4000-8000-000000000001')$$,'reenvio permitido mesmo após saldo zero');
select is((select b.quantity-sum(m.quantity) from batch_receipts b join stock_movements m on m.batch_id=b.id group by b.quantity),0::numeric,'saldo exato zero');
select throws_ok($$insert into stock_movements(organization_id) values ('92000000-0000-4000-8000-000000000001')$$,'42501',null,'cliente não insere evento diretamente');
select throws_ok($$delete from stock_movements$$,'42501',null,'cliente não apaga histórico');
select throws_ok($$update stock_movements set quantity=1$$,'42501',null,'cliente não altera histórico');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from stock_movements),0::bigint,'empresa B não lê movimentos A');
select throws_ok($$select record_movement('92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000001','consumption',0.75,null,'98000000-0000-4000-8000-000000000001')$$,'42501',null,'empresa B não acessa replay');
set local role anon;
select throws_ok('select * from stock_movements','42501',null,'anônimo não lê');
select * from finish();
rollback;
